 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = next(value for value, _ in counts.most_common() if value != background)
    out = [row[:] for row in grid]

    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(marks, marks[1:]):
            if b - a <= 4:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            if b - a <= 4:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
