 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Long horizontal marker bands define rails; fill only their bounded gaps.
    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value == marker]
        if len(marks) >= max(2, w // 4):
            for a, b in zip(marks, marks[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # Complete the outer vertical rails and any substantial internal rail.
    col_marks = [[r for r in range(h) if grid[r][c] == marker] for c in range(w)]
    active = [c for c, marks in enumerate(col_marks) if marks and
              (c == min(i for i, m in enumerate(col_marks) if m) or
               c == max(i for i, m in enumerate(col_marks) if m) or
               len(marks) >= max(4, h // 3))]
    for c in active:
        marks = col_marks[c]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2

    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
