    boundary_cols = [c for r in (top, bottom) for c, value in enumerate(grid[r]) if value == marker]
    left, right = min(boundary_cols), max(boundary_cols)

    # Complete the horizontal rail gaps within the frame.
    for r in rails:
        marks = [c for c in range(left, right + 1) if grid[r][c] == marker]
        for c in range(left, right + 1):
            if grid[r][c] == background and (c < marks[0] or c > marks[-1] or
                    any(a < c < b for a, b in zip(marks, marks[1:]))):
                out[r][c] = 2

    # Complete the two outer vertical rails, including a missing corner cell.
    for c in (left, right):
        for r in range(top, bottom + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    # A clearly repeated internal marker column is also a rail; fill only its gaps.
    min_internal = max(4, h // 3)
