def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    marker = min(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Dense marker rows are horizontal rails; their first/last markers delimit each span.
    row_threshold = max(3, w // 4)
    rails = [r for r, row in enumerate(grid)
             if sum(value == marker for value in row) >= row_threshold]
    if len(rails) < 2:
        rails = [r for r, row in enumerate(grid)
                 if sum(value == marker for value in row) >= 2]
    if not rails:
        return out

    top, bottom = min(rails), max(rails)
    row_rails = [r for r in rails if top <= r <= bottom]
    for r in row_rails:
        cols = [c for c, value in enumerate(grid[r]) if value == marker]
        if len(cols) >= 2:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] != marker:
                    out[r][c] = 2

    marker_cols = [c for c in range(w) if any(grid[r][c] == marker for r in range(h))]
    if marker_cols:
        left, right = min(marker_cols), max(marker_cols)
        vertical_rails = {left, right}
        min_internal = max(4, h // 3)
        for c in range(left + 1, right):
            marks = [r for r in range(top, bottom + 1) if grid[r][c] == marker]
            if len(marks) >= min_internal:
                vertical_rails.add(c)
        for c in vertical_rails:
            for r in range(top, bottom + 1):
                if grid[r][c] != marker:
                    out[r][c] = 2

    return out


